class Memento {
  // Only Editor can construct or read this — fields are effectively opaque outside it
  constructor(private readonly content: string, private readonly cursorPosition: number) {}
  private getState() { return { content: this.content, cursorPosition: this.cursorPosition }; }
  static restore(editor: Editor, memento: Memento) {
    editor.setState(memento.getState());
  }
}

class Editor {
  private content = "";
  private cursorPosition = 0;

  save(): Memento { return new Memento(this.content, this.cursorPosition); }
  setState(state: { content: string; cursorPosition: number }) {
    this.content = state.content;
    this.cursorPosition = state.cursorPosition;
  }
}

class History {
  private snapshots: Memento[] = [];
  push(memento: Memento) { this.snapshots.push(memento); }
  pop(): Memento | undefined { return this.snapshots.pop(); } // opaque — never inspected
}
